import itertools
P={'P1':(2,3,-1),'P2':(3,1,1),'P3':(5,-2,3),'P4':(3,3,3)}
d={(a,b):sum(abs(x-y) for x,y in zip(P[a],P[b])) for a,b in itertools.combinations(P,2)}
print(d)  # P1P2=5 P1P3=12 P1P4=5 P2P3=7 P2P4=4 P3P4=7
m=min(d.values()); print(m,[k for k,v in d.items() if v==m])  # 4 [('P2','P4')] -> unique minimum
